-- Gowave pre-release schema baseline; see schema_export_test.go.
CREATE TABLE IF NOT EXISTS `admin` (`uuid` varchar(64),`username` varchar(64),`password_hash` varchar(255),`role` varchar(32) DEFAULT "ADMIN",`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_admin_username` ON `admin`(`username`);
CREATE TABLE IF NOT EXISTS `subscription_page_config` (`uuid` varchar(64),`view_position` integer DEFAULT 0,`name` varchar(255),`tags` text[] DEFAULT "{}",`config` text DEFAULT "{}",`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_subscription_page_config_name` ON `subscription_page_config`(`name`);
CREATE TABLE IF NOT EXISTS `external_squads` (`uuid` varchar(64),`view_position` integer DEFAULT 0,`name` varchar(64),`tags` text[] DEFAULT "{}",`subscription_settings` text DEFAULT "{}",`host_overrides` text DEFAULT "{}",`response_headers_add` text DEFAULT "{}",`response_headers_remove` text[] DEFAULT "{}",`hwid_settings` text DEFAULT "{}",`custom_remarks` text DEFAULT "{}",`subpage_config_uuid` varchar(64),`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`),CONSTRAINT `fk_subscription_page_config_external_squads` FOREIGN KEY (`subpage_config_uuid`) REFERENCES `subscription_page_config`(`uuid`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_external_squads_name` ON `external_squads`(`name`);
CREATE TABLE IF NOT EXISTS `users` (`revision` integer DEFAULT 1,`id` integer PRIMARY KEY AUTOINCREMENT,`short_uuid` varchar(64),`username` varchar(64),`status` varchar(16) DEFAULT "ACTIVE",`traffic_limit_bytes` integer DEFAULT 0,`traffic_limit_strategy` varchar(32) DEFAULT "NO_RESET",`expire_at` datetime,`last_traffic_reset_at` datetime,`sub_revoked_at` datetime,`trojan_password` varchar(64),`vless_uuid` varchar(64),`ss_password` varchar(64),`description` text,`tag` varchar(64),`telegram_id` integer,`email` varchar(128),`hwid_device_limit` integer,`external_squad_uuid` varchar(64),`last_triggered_threshold` integer DEFAULT 0,`created_at` datetime,`updated_at` datetime,CONSTRAINT `fk_users_external_squad` FOREIGN KEY (`external_squad_uuid`) REFERENCES `external_squads`(`uuid`) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS `idx_users_expire_at` ON `users`(`expire_at`);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_users_username` ON `users`(`username`);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_users_short_uuid` ON `users`(`short_uuid`);
CREATE TABLE IF NOT EXISTS `config_profiles` (`uuid` varchar(64),`view_position` integer DEFAULT 1,`name` varchar(64),`tags` text[] DEFAULT "{}",`config` text,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_config_profiles_name` ON `config_profiles`(`name`);
CREATE TABLE IF NOT EXISTS `infra_providers` (`uuid` varchar(64),`name` varchar(128),`favicon_link` varchar(255),`login_url` varchar(255),`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_infra_providers_name` ON `infra_providers`(`name`);
CREATE TABLE IF NOT EXISTS `node_plugin` (`uuid` varchar(64),`view_position` integer DEFAULT 0,`name` varchar(255),`tags` text[] DEFAULT "{}",`plugin_config` text DEFAULT "{}",`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE TABLE IF NOT EXISTS `nodes` (`id` integer PRIMARY KEY AUTOINCREMENT,`uuid` varchar(64),`name` varchar(64),`address` varchar(255),`port` integer DEFAULT 443,`proxy_url` varchar(255),`is_connected` numeric DEFAULT false,`is_connecting` numeric DEFAULT false,`is_disabled` numeric DEFAULT false,`country_code` varchar(8) DEFAULT "XX",`traffic_limit_bytes` integer DEFAULT 0,`traffic_used_bytes` integer DEFAULT 0,`is_traffic_tracking_active` numeric DEFAULT false,`traffic_reset_day` integer DEFAULT 1,`notify_percent` integer DEFAULT 80,`view_position` integer DEFAULT 1,`consumption_multiplier` integer DEFAULT 1000000000,`node_consumption_multiplier` integer DEFAULT 1000000000,`tags` text[] DEFAULT "{}",`integration_uuids` uuid[] DEFAULT "{}",`ips` text DEFAULT "[]",`active_config_profile_uuid` varchar(64),`provider_uuid` varchar(64),`active_plugin_uuid` varchar(64),`note` text,`last_status_change` datetime,`last_status_message` text,`created_at` datetime,`updated_at` datetime,CONSTRAINT `fk_config_profiles_nodes` FOREIGN KEY (`active_config_profile_uuid`) REFERENCES `config_profiles`(`uuid`),CONSTRAINT `fk_infra_providers_nodes` FOREIGN KEY (`provider_uuid`) REFERENCES `infra_providers`(`uuid`),CONSTRAINT `fk_nodes_active_plugin` FOREIGN KEY (`active_plugin_uuid`) REFERENCES `node_plugin`(`uuid`) ON DELETE SET NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_nodes_address` ON `nodes`(`address`);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_nodes_name` ON `nodes`(`name`);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_nodes_uuid` ON `nodes`(`uuid`);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_nodes_id` ON `nodes`(`id`);
CREATE TABLE IF NOT EXISTS `user_traffic` (`id` integer PRIMARY KEY AUTOINCREMENT,`used_traffic_bytes` integer DEFAULT 0,`lifetime_used_traffic_bytes` integer DEFAULT 0,`online_at` datetime,`last_connected_node_uuid` varchar(64),`first_connected_at` datetime,CONSTRAINT `fk_user_traffic_last_connected_node` FOREIGN KEY (`last_connected_node_uuid`) REFERENCES `nodes`(`uuid`) ON DELETE SET NULL,CONSTRAINT `fk_users_traffic` FOREIGN KEY (`id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `integrations` (`uuid` varchar(64),`name` varchar(30),`description` varchar(255),`config` text,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_integrations_name` ON `integrations`(`name`);
CREATE TABLE IF NOT EXISTS `nodes_user_usage_history` (`node_id` integer,`created_at` datetime,`user_id` integer,`total_bytes` integer,`updated_at` datetime,PRIMARY KEY (`node_id`,`created_at`,`user_id`),CONSTRAINT `fk_nodes_user_usage_history_node` FOREIGN KEY (`node_id`) REFERENCES `nodes`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_nodes_user_usage_history_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS `idx_nodes_user_usage_history_user_created` ON `nodes_user_usage_history`(`user_id`,`created_at`);
CREATE TABLE IF NOT EXISTS `nodes_usage_history` (`node_uuid` varchar(64),`created_at` datetime,`download_bytes` integer,`upload_bytes` integer,`total_bytes` integer,`updated_at` datetime,PRIMARY KEY (`node_uuid`,`created_at`),CONSTRAINT `fk_nodes_usage_history_node` FOREIGN KEY (`node_uuid`) REFERENCES `nodes`(`uuid`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `config_profile_inbounds` (`uuid` varchar(64),`profile_uuid` varchar(64),`tag` varchar(64),`type` varchar(32),`network` varchar(32),`security` varchar(32),`port` integer,`raw_inbound` text,PRIMARY KEY (`uuid`),CONSTRAINT `fk_config_profiles_inbounds` FOREIGN KEY (`profile_uuid`) REFERENCES `config_profiles`(`uuid`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_config_profile_inbounds_tag` ON `config_profile_inbounds`(`tag`);
CREATE INDEX IF NOT EXISTS `idx_config_profile_inbounds_profile_uuid` ON `config_profile_inbounds`(`profile_uuid`);
CREATE TABLE IF NOT EXISTS `subscription_templates` (`uuid` varchar(64),`view_position` integer DEFAULT 0,`name` varchar(255),`tags` text[] DEFAULT "{}",`template_type` varchar(32),`template_yaml` text,`template_json` text,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_subscription_templates_type_name` ON `subscription_templates`(`template_type`,`name`);
CREATE TABLE IF NOT EXISTS `hosts` (`uuid` varchar(64),`view_position` integer DEFAULT 1,`remark` varchar(128),`address` varchar(255),`port` integer DEFAULT 443,`path` varchar(255),`sni` varchar(255),`host` varchar(255),`alpn` varchar(64),`fingerprint` varchar(64) DEFAULT "chrome",`security_layer` varchar(32) DEFAULT "DEFAULT",`xhttp_extra_params` text,`mux_params` text,`sockopt_params` text,`final_mask` text,`is_disabled` numeric DEFAULT false,`server_description` varchar(255),`vless_route_id` integer,`pinned_peer_cert_sha256` varchar(255),`verify_peer_cert_by_name` varchar(255),`shuffle_host` numeric DEFAULT false,`mihomo_x25519` numeric DEFAULT false,`mihomo_ip_version` varchar(32),`xray_json_template_uuid` varchar(64),`keep_sni_blank` numeric DEFAULT false,`exclude_from_subscription_types` text[] DEFAULT "{}",`mapper` text DEFAULT "{}",`internal_squads_mode` varchar(32) DEFAULT "EXCLUDE",`tags` text[] DEFAULT "{}",`is_hidden` numeric DEFAULT false,`override_sni_from_address` numeric DEFAULT false,`config_profile_uuid` varchar(64),`config_profile_inbound_uuid` varchar(64),PRIMARY KEY (`uuid`),CONSTRAINT `fk_config_profile_inbounds_hosts` FOREIGN KEY (`config_profile_inbound_uuid`) REFERENCES `config_profile_inbounds`(`uuid`),CONSTRAINT `fk_config_profiles_hosts` FOREIGN KEY (`config_profile_uuid`) REFERENCES `config_profiles`(`uuid`),CONSTRAINT `fk_subscription_templates_host_links` FOREIGN KEY (`xray_json_template_uuid`) REFERENCES `subscription_templates`(`uuid`));
CREATE TABLE IF NOT EXISTS `hosts_to_nodes` (`host_uuid` varchar(64),`node_uuid` varchar(64),PRIMARY KEY (`host_uuid`,`node_uuid`),CONSTRAINT `fk_hosts_to_nodes_node` FOREIGN KEY (`node_uuid`) REFERENCES `nodes`(`uuid`) ON DELETE CASCADE,CONSTRAINT `fk_hosts_to_nodes_host` FOREIGN KEY (`host_uuid`) REFERENCES `hosts`(`uuid`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `internal_squads` (`uuid` varchar(64),`view_position` integer DEFAULT 0,`name` varchar(64),`tags` text[] DEFAULT "{}",`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE UNIQUE INDEX IF NOT EXISTS `idx_internal_squads_name` ON `internal_squads`(`name`);
CREATE TABLE IF NOT EXISTS `internal_squad_host_links` (`host_uuid` varchar(64),`squad_uuid` varchar(64),PRIMARY KEY (`host_uuid`,`squad_uuid`),CONSTRAINT `fk_internal_squad_host_links_host` FOREIGN KEY (`host_uuid`) REFERENCES `hosts`(`uuid`) ON DELETE CASCADE,CONSTRAINT `fk_internal_squad_host_links_squad` FOREIGN KEY (`squad_uuid`) REFERENCES `internal_squads`(`uuid`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `config_profile_inbounds_to_nodes` (`config_profile_inbound_uuid` varchar(64),`node_uuid` varchar(64),PRIMARY KEY (`config_profile_inbound_uuid`,`node_uuid`),CONSTRAINT `fk_config_profile_inbounds_to_nodes_node` FOREIGN KEY (`node_uuid`) REFERENCES `nodes`(`uuid`) ON DELETE CASCADE,CONSTRAINT `fk_config_profile_inbounds_node_links` FOREIGN KEY (`config_profile_inbound_uuid`) REFERENCES `config_profile_inbounds`(`uuid`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `remnawave_settings` (`id` integer PRIMARY KEY AUTOINCREMENT,`title` varchar(128) DEFAULT "Remnawave",`logo_url` varchar(255),`is_login_allowed` numeric DEFAULT true,`is_register_allowed` numeric DEFAULT false,`password_auth_enabled` numeric DEFAULT true,`passkey_settings` text DEFAULT "{}",`oauth2_settings` text DEFAULT "{}",`password_settings` text DEFAULT "{}",`branding_settings` text DEFAULT "{}");
CREATE TABLE IF NOT EXISTS `api_tokens` (`uuid` varchar(64),`name` text,`expire_at` datetime,`scopes` text[] DEFAULT "{}",`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE TABLE IF NOT EXISTS `subscription_settings` (`uuid` varchar(64),`serve_json_at_base_subscription` numeric DEFAULT false,`is_show_custom_remarks` numeric DEFAULT true,`custom_remarks` text DEFAULT "{}",`custom_response_headers` text DEFAULT "{}",`randomize_hosts` numeric DEFAULT false,`response_rules` text DEFAULT "{}",`hwid_settings` text DEFAULT "{}",`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE TABLE IF NOT EXISTS `config_profile_snippets` (`name` varchar(255),`snippet` text DEFAULT "{}",`created_at` datetime,PRIMARY KEY (`name`));
CREATE TABLE IF NOT EXISTS `shared_lists` (`name` varchar(255),`config` text DEFAULT "{}",`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`name`));
CREATE TABLE IF NOT EXISTS `internal_squad_members` (`internal_squad_uuid` varchar(64),`user_id` integer,PRIMARY KEY (`internal_squad_uuid`,`user_id`),CONSTRAINT `fk_internal_squad_members_squad` FOREIGN KEY (`internal_squad_uuid`) REFERENCES `internal_squads`(`uuid`) ON DELETE CASCADE,CONSTRAINT `fk_internal_squad_members_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS `idx_internal_squad_members_user_id` ON `internal_squad_members`(`user_id`);
CREATE TABLE IF NOT EXISTS `internal_squad_inbounds` (`internal_squad_uuid` varchar(64),`inbound_uuid` varchar(64),PRIMARY KEY (`internal_squad_uuid`,`inbound_uuid`),CONSTRAINT `fk_internal_squad_inbounds_squad` FOREIGN KEY (`internal_squad_uuid`) REFERENCES `internal_squads`(`uuid`) ON DELETE CASCADE,CONSTRAINT `fk_config_profile_inbounds_squad_links` FOREIGN KEY (`inbound_uuid`) REFERENCES `config_profile_inbounds`(`uuid`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `external_squads_templates` (`external_squad_uuid` varchar(64),`template_type` varchar(32),`template_uuid` varchar(64),PRIMARY KEY (`external_squad_uuid`,`template_type`),CONSTRAINT `fk_external_squads_templates_squad` FOREIGN KEY (`external_squad_uuid`) REFERENCES `external_squads`(`uuid`) ON DELETE CASCADE,CONSTRAINT `fk_external_squads_templates_template` FOREIGN KEY (`template_uuid`) REFERENCES `subscription_templates`(`uuid`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `infra_billing_nodes` (`uuid` varchar(64),`node_uuid` varchar(64),`name` varchar(128),`provider_uuid` varchar(64),`next_billing_at` datetime,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`),CONSTRAINT `fk_infra_providers_billing_nodes` FOREIGN KEY (`provider_uuid`) REFERENCES `infra_providers`(`uuid`) ON DELETE CASCADE,CONSTRAINT `fk_infra_billing_nodes_node` FOREIGN KEY (`node_uuid`) REFERENCES `nodes`(`uuid`) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS `idx_infra_billing_nodes_next_billing_at` ON `infra_billing_nodes`(`next_billing_at`);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_infra_billing_nodes_node_provider` ON `infra_billing_nodes`(`node_uuid`,`provider_uuid`);
CREATE TABLE IF NOT EXISTS `infra_billing_history` (`uuid` varchar(64),`provider_uuid` varchar(64),`amount` real,`billed_at` datetime,PRIMARY KEY (`uuid`),CONSTRAINT `fk_infra_providers_billing_items` FOREIGN KEY (`provider_uuid`) REFERENCES `infra_providers`(`uuid`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `hwid_user_devices` (`hwid` varchar(128),`user_id` integer,`platform` varchar(64),`os_version` varchar(64),`device_model` varchar(128),`user_agent` text,`request_ip` varchar(64),`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`hwid`,`user_id`),CONSTRAINT `fk_hwid_user_devices_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS `idx_hwid_user_devices_user_id` ON `hwid_user_devices`(`user_id`);
CREATE TABLE IF NOT EXISTS `user_subscription_request_history` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`request_ip` varchar(64),`user_agent` text,`srr_rule_name` varchar(128),`srr_response_type` varchar(64) DEFAULT "UNKNOWN",`request_at` datetime,CONSTRAINT `fk_user_subscription_request_history_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS `idx_user_subscription_request_history_user_id` ON `user_subscription_request_history`(`user_id`);
CREATE TABLE IF NOT EXISTS `entity_meta` (`entity_id` varchar(64),`entity_type` varchar(32),`metadata` text DEFAULT "{}",PRIMARY KEY (`entity_id`,`entity_type`));
CREATE TABLE IF NOT EXISTS `keygen` (`uuid` varchar(64),`ca_cert` text,`ca_key` text,`client_cert` text,`client_key` text,`pub_key` text,`priv_key` text,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`uuid`));
CREATE TABLE IF NOT EXISTS `passkeys` (`id` varchar(255),`admin_uuid` varchar(64),`public_key` blob,`credential_data` text,`counter` integer DEFAULT 0,`device_type` varchar(32) DEFAULT "singleDevice",`backed_up` numeric DEFAULT false,`transports` varchar(255),`passkey_provider` varchar(255) DEFAULT "Unknown",`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`id`),CONSTRAINT `fk_passkeys_admin` FOREIGN KEY (`admin_uuid`) REFERENCES `admin`(`uuid`) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS `idx_passkeys_admin_uuid` ON `passkeys`(`admin_uuid`);
CREATE TABLE IF NOT EXISTS `auth_challenges` (`id` varchar(255),`purpose` varchar(64),`admin_uuid` varchar(64),`data` text,`expires_at` datetime,`created_at` datetime,PRIMARY KEY (`id`));
CREATE INDEX IF NOT EXISTS `idx_auth_challenges_expires_at` ON `auth_challenges`(`expires_at`);
CREATE INDEX IF NOT EXISTS `idx_auth_challenges_purpose` ON `auth_challenges`(`purpose`);
CREATE TABLE IF NOT EXISTS `jobs` (`id` varchar(64),`kind` varchar(64),`entity_id` varchar(64),`target` varchar(255),`revision` integer,`payload` text,`state` varchar(16) DEFAULT "pending",`attempts` integer,`available_at` datetime,`lease_until` datetime,`last_error` text,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`id`));
CREATE INDEX IF NOT EXISTS `idx_jobs_lease_until` ON `jobs`(`lease_until`);
CREATE INDEX IF NOT EXISTS `idx_jobs_available_at` ON `jobs`(`available_at`);
CREATE INDEX IF NOT EXISTS `idx_jobs_state` ON `jobs`(`state`);
CREATE INDEX IF NOT EXISTS `idx_jobs_target` ON `jobs`(`target`);
CREATE INDEX IF NOT EXISTS `idx_jobs_entity_id` ON `jobs`(`entity_id`);
CREATE INDEX IF NOT EXISTS `idx_jobs_kind` ON `jobs`(`kind`);
CREATE TABLE IF NOT EXISTS `scheduled_executions` (`id` varchar(128),`executed_at` datetime,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `user_meta` (`user_id` integer PRIMARY KEY AUTOINCREMENT,`metadata` text,CONSTRAINT `fk_user_meta_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `node_meta` (`node_id` integer PRIMARY KEY AUTOINCREMENT,`metadata` text,CONSTRAINT `fk_node_meta_node` FOREIGN KEY (`node_id`) REFERENCES `nodes`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `torrent_blocker_reports` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`node_id` integer,`report` text,`created_at` datetime,CONSTRAINT `fk_torrent_blocker_reports_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_torrent_blocker_reports_node` FOREIGN KEY (`node_id`) REFERENCES `nodes`(`id`) ON DELETE CASCADE);
